                "sampleValue": "B座 8F 会议室"
              }
            }
          }
        }
      }
    },
    "ui": {
      "dateLabel": {
        "type": "string",
        "description": "卡片展示的日程日期标签。",
        "sampleValue": "今日日程"
      },
      "timelineLabel": {
        "type": "string",
        "description": "时间轴区域的短标题。",
        "sampleValue": "时间轴"
      },
      "actionLabel": {
        "type": "string",
        "description": "进入第一条日程详情的动作文案。",
        "sampleValue": "查看详情"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合用于日程卡片的服务识别。"
    },
    {
      "src": "resources/base/media/icon_meeting.png",
      "description": "会议图标，适合用于会议或当下日程的主对象识别。"
    },
    {
      "src": "resources/base/media/icon_time.png",
      "description": "时间图标，适合用于日程时间或时间轴辅助识别。"
    }
  ]
}

